
/* Self-contained Beitrittserklaerung PDF (base64). Opens in a new tab via Blob URL so the
   single HTML file works on any device without a separate PDF next to it. */
(function(){
  "use strict";
  var B64="";
  var _url=null;
  function blobUrl(){
    if(_url) return _url;
    var bin=atob(B64), n=bin.length, arr=new Uint8Array(n);
    for(var i=0;i<n;i++){ arr[i]=bin.charCodeAt(i); }
    _url=URL.createObjectURL(new Blob([arr],{type:"application/pdf"}));
    return _url;
  }
  document.addEventListener("click", function(e){
    var a=e.target.closest ? e.target.closest("#vm-pdf-open") : null;
    if(!a) return;
    e.preventDefault();
    try{
      var url=blobUrl();
      var w=window.open(url,"_blank");
      if(!w){ var l=document.createElement("a"); l.href=url; l.download="Beitrittserklaerung.pdf"; document.body.appendChild(l); l.click(); l.remove(); }
    }catch(err){
      var href=a.getAttribute("href"); if(href){ window.location.href=href; }
    }
  });
})();
